// Foresignal mail gate (docs/cookbooks/n8n-imap.md). Runs once for all items.
// Keeps a message only when the sender is allowlisted AND this mailbox's own
// mail server recorded dkim=pass and dmarc=pass for it; everything else is dropped.
// Mail text is untrusted: nothing here follows links or loads remote content.
const ALLOWED_SENDERS = ['alerts@example.org', 'noreply@status.example.com'];  // edit
const AUTHSERV_ID = 'mx.example.net';   // the authserv-id your receiving server writes (edit)

function stripHtml(html) {
  return String(html || '')
    .replace(/<(script|style|head)[\s\S]*?<\/\1>/gi, ' ')
    .replace(/<[^>]+>/g, ' ')
    .replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&').replace(/&lt;/g, '<').replace(/&gt;/g, '>')
    .replace(/&quot;/g, '"').replace(/&#39;/g, "'");
}

const out = [];
for (const item of $input.all()) {
  const mail = item.json;
  const from = String(mail.from?.value?.[0]?.address || '').toLowerCase();
  if (!ALLOWED_SENDERS.includes(from)) continue;
  // headers maps a lowercase name to its full line; with repeated headers only
  // one survives, so a message carrying a second Authentication-Results fails closed.
  const line = String(mail.headers?.['authentication-results'] || '');
  const value = line.replace(/^authentication-results:\s*/i, '').trim();
  if (!value.toLowerCase().startsWith(AUTHSERV_ID.toLowerCase())) continue;
  if (!/\bdkim=pass\b/i.test(value) || !/\bdmarc=pass\b/i.test(value)) continue;

  const text = (mail.text ? String(mail.text) : stripHtml(mail.html)).replace(/\s+/g, ' ').trim();
  const link = (text.match(/https?:\/\/[^\s<>"')\]]+/) || [null])[0];
  const subject = String(mail.subject || '(no subject)').slice(0, 300);
  const messageId = String(mail.messageId || '').replace(/[<>]/g, '').slice(0, 200)
    || (from + ':' + subject + ':' + String(mail.date || '')).slice(0, 200);
  const sent = mail.date ? new Date(mail.date) : null;

  out.push({ json: { record: {
    externalId: messageId,
    kind: 'mail-notice',
    eventTime: sent && !isNaN(sent) ? sent.toISOString() : null,
    payload: { subject, from, link, excerpt: text.slice(0, 280) }
  } } });
}
return out;
